select `tb_daftar`.`peserta_id` AS `peserta_id`,`tb_daftar`.`tgl_daftar` AS `tgl_daftar`,`tb_daftar`.`ref_id` AS `ref_id`,`tb_daftar`.`nm_depan` AS `nm_depan`,`tb_daftar`.`nm_tengah` AS `nm_tengah`,`tb_daftar`.`nm_belakang` AS `nm_belakang`,`tb_daftar`.`nama` AS `nama`,`tb_daftar`.`kelamin_id` AS `kelamin_id`,if((`tb_daftar`.`kelamin_id` = 1),'P',if((`tb_daftar`.`kelamin_id` = 2),'P','-')) AS `kelamin`,`tb_daftar`.`tempat_lahir` AS `tempat_lahir`,`tb_daftar`.`tgl_lahir` AS `tgl_lahir`,`tb_daftar`.`alamat1` AS `alamat1`,`tb_daftar`.`alamat2` AS `alamat2`,`tb_daftar`.`kota` AS `kota`,`tb_daftar`.`kelas_id` AS `kelas_id`,`mt_kelas`.`kelas` AS `kelas`,`tb_daftar`.`harga` AS `harga`,`tb_daftar`.`diskon` AS `diskon`,`tb_daftar`.`biaya` AS `biaya`,`tb_daftar`.`counter` AS `counter`,`tb_daftar`.`tgl_input` AS `tgl_input`,`tb_daftar`.`tgl_update` AS `tgl_update`,`tb_daftar`.`user_id` AS `user_id`,`mt_user`.`user_name` AS `user_name`,`mt_app`.`app` AS `app`,`tb_daftar`.`log` AS `log`,year(`tb_daftar`.`tgl_daftar`) AS `tahun`,month(`tb_daftar`.`tgl_daftar`) AS `bulan`,dayofmonth(`tb_daftar`.`tgl_daftar`) AS `tgl`,`mt_area`.`area_id` AS `area_id`,`mt_area`.`area_kode` AS `area_kode`,`mt_area`.`area_nama` AS `area_nama`
from `tb_daftar`
join `mt_kelas` on `tb_daftar`.`kelas_id` = `mt_kelas`.`kelas_id`  and tb_daftar.area_id = mt_kelas.area_id
join `mt_user` on `tb_daftar`.`user_id` = `mt_user`.`user_id`
join `mt_app` on `mt_user`.`app_id` = `mt_app`.`app_id`
join `mt_area` on `mt_user`.`area_id` = `mt_area`.`area_id`
